export const SLAM_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/slam-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSlamStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SLAM_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
